data_y2 = [[float(t), float(d)] for t, d in zip(temp_clean, dtg_display)]

# Find Residue at 800 C
idx_800 = np.argmin(np.abs(temp_clean - 800))
residue_temp = temp_clean[idx_800]
residue_weight = weight_clean[idx_800]

# Find Peak DTG above 150 C
mask_peak = temp_clean > 150
if np.any(mask_peak):
    dtg_for_peak = dtg_display[mask_peak]
    temp_for_peak = temp_clean[mask_peak]
    idx_peak_local = np.argmax(dtg_for_peak)
    peak_temp = temp_for_peak[idx_peak_local]
    peak_val = dtg_for_peak[idx_peak_local]
else:
